#include <cstring>
#include <iostream>
using namespace std;

int main() {
    char name[] = "Goa";
    cout << strlen(name) << endl;
    cout << sizeof(name) << endl;
    cout << name << endl;
    return 0;
}

#include <cstring>
#include <iostream>
using namespace std;

int main() {
    char a[] = "goa";
    char b[] = "goa";
    cout << (strcmp(a, b) == 0) << endl;
    return 0;
}

